/* Auth block layout. Visuals come from AuthLayout, AuthCard and the tokens. */

.frame {
  width: 100%;
  height: 100%;
}

.mark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: var(--tracking-display);
  color: inherit;
}

.glyph {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-sm);
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
  font-size: 14px;
  color: var(--ink-inverse);
}

.help {
  font-size: var(--text-small);
  font-weight: 700;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.otp {
  display: flex;
  justify-content: center;
}

.alt {
  font-size: var(--text-small);
  color: var(--ink-muted);
  text-align: center;
}

.link {
  padding: 0;
  border: 0;
  background: none;
  font-weight: 700;
  color: var(--ink-brand);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.link:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-2xs);
}

.setup {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

@media (max-width: 480px) {
  .setup {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
  }
}

.qr {
  display: block;
  width: 148px;
  height: 148px;
  border-radius: var(--r-md);
  box-shadow: inset 0 0 0 1px var(--line);
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: var(--text-small);
  color: var(--ink-body);
}

.secret {
  align-self: flex-start;
  padding: 6px 10px;
  border-radius: var(--r-sm);
  background: var(--surface-sunken);
  box-shadow: inset 0 0 0 1px var(--line);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--ink-heading);
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 480px) {
  .row {
    grid-template-columns: minmax(0, 1fr);
  }
}

.between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

"use client";

import { AuthCard, AuthLayout } from "@/components/shell/AuthCard";
import { Button } from "@/components/ui/Button/Button";
import { Field } from "@/components/ui/Field/Field";
import { IconLock, IconShield } from "@/components/ui/Icon/Icon";
import { TextInput } from "@/components/ui/TextInput/TextInput";
import styles from "./Auth.module.css";

export type AuthResetProps = {
  /** Fill the parent instead of the viewport. */
  contained?: boolean;
};

/** Reset a password: ask for the email, send a link. Drop it at app/reset-password. */
export default function AuthReset({ contained }: AuthResetProps) {
  return (
    <div className={contained ? styles.frame : undefined}>
      <AuthLayout
        contained={contained}
        header={
          <span className={styles.mark}>
            <span className={styles.glyph} aria-hidden="true">
              A
            </span>
            Acme
          </span>
        }
        footer={
          <>
            <IconShield size={14} />
            For your security, the link works once and expires after an hour.
          </>
        }
      >
        <AuthCard icon={<IconLock size={22} />} title="Reset your password" subtitle="Enter the email you sign in with. We will send you a link to choose a new password." back={{ href: "#login", label: "Back to sign in" }}>
          <form onSubmit={(e) => e.preventDefault()} style={{ display: "contents" }}>
            <Field label="Work email">
              <TextInput type="email" autoComplete="email" placeholder="jane@acme.example" />
            </Field>
            <Button type="submit" size="lg" fullWidth>
              Send reset link
            </Button>
          </form>
        </AuthCard>
      </AuthLayout>
    </div>
  );
}

import AuthReset from "@/components/blocks/auth-reset";

export default function Page() {
  return <AuthReset />;
}
